// backend/src/controllers/support.controller.ts
var SupportController = class {
  static async createTicket(req, res, next) {
    try {
      const userId = req.user?.id || "usr-anonymous";
      const distributorId = req.user?.distributorProfileId || null;
      const input = req.body;
      const ticket = await SupportService.createTicket(
        userId,
        distributorId,
        input,
        req.user?.email,
        req.user?.email
      );
      res.status(201).json({
        success: true,
        message: "Support ticket submitted successfully.",
        data: ticket
      });
    } catch (err) {
      next(err);
    }
  }
  static async getMyTickets(req, res, next) {
    try {
      const userId = req.user?.id || "usr-anonymous";
      const distributorId = req.user?.distributorProfileId || null;
      const query = req.query;
      const result = await SupportService.getMyTickets(userId, distributorId, query);
      res.status(200).json({
        success: true,
        data: result.data,
        pagination: {
          total: result.total,
          page: Number(query.page || 1),
          limit: Number(query.limit || 20)
        }
      });
    } catch (err) {
      next(err);
    }
  }
  static async getTicketById(req, res, next) {
    try {
      const { id } = req.params;
      const userId = req.user?.id;
      const isAdmin = req.user?.role === "ADMIN" || req.user?.role === "SUPER_ADMIN";
      const ticket = await SupportService.getTicketById(id, userId, isAdmin);
      res.status(200).json({
        success: true,
        data: ticket
      });
    } catch (err) {
      next(err);
    }
  }
  static async addMessage(req, res, next) {
    try {
      const { id } = req.params;
      const userId = req.user?.id || "usr-anonymous";
      const input = req.body;
      const isAdmin = req.user?.role === "ADMIN" || req.user?.role === "SUPER_ADMIN";
      const senderName = req.user?.distributorCode || req.user?.email;
      const message = await SupportService.addMessage(id, userId, input, senderName, isAdmin);
      res.status(201).json({
        success: true,
        message: "Message added to ticket.",
        data: message
      });
    } catch (err) {
      next(err);
    }
  }
  static async closeTicket(req, res, next) {
    try {
      const { id } = req.params;
      const userId = req.user?.id;
      const isAdmin = req.user?.role === "ADMIN" || req.user?.role === "SUPER_ADMIN";
      const ticket = await SupportService.closeTicket(id, userId, isAdmin);
      res.status(200).json({
        success: true,
        message: "Support ticket closed successfully.",
        data: ticket
      });
    } catch (err) {
      next(err);
    }
  }
};

